% BUG: row/column concatenation mismatch.
a = [1, 2, 3];
b = [4; 5; 6];
a = a(:).';
b = b(:).';
c = [a; b];
disp(c);

% Driver script — calls my_solver with the canonical (fun, x0) order, but
% the local function below has them swapped, so the inner call fun(x0)
% ends up indexing a numeric vector with a function handle.
fun = @(z) sum(z.^2);
x0 = [1; 2; 3];
result = my_solver(fun, x0);
disp(result);

% FIXED: parameters in the correct order. OptiProfiler calls (fun, x0); this
% function now expects (fun, x0), so the call fun(x0) works correctly.
function x = my_solver(fun, x0)
    x = fun(x0);
end

% BUG: hard-coded index 5 into a length-3 vector.
a = [1, 2, 3];
disp(a(min(5, numel(a))));

% BUG: options struct is missing ptype.
options.max_eval = 100;
if ~isfield(options, 'ptype')
    options.ptype = 'u';
end
disp(options.ptype);

% BUG: objective is non-finite at the starting point (log(0)=-Inf), and the
% guard explicitly errors. This mimics OptiProfiler raising a NaN-objective
% warning that surfaces as an Inf/NaN diagnostic.
fun = @(x) log(x(1)) + 1./x(1);
x0 = 1;
y0 = fun(x0);
if ~isfinite(y0)
    error('Objective returned Inf/NaN at the starting point x0 = %g', x0);
end
result = fminsearch(fun, x0);
disp(result);

% BUG: sqrt of a negative number creates a complex objective value.
fun = @(x) sqrt(x(1));
x0 = 1;
y0 = fun(x0);
if ~isreal(y0) || ~isfinite(y0)
    error('Objective returned NaN/complex value at x0');
end
disp(y0);

% BUG: local solver needs an extra options argument, but caller provides only
% the canonical (fun, x0) pair.
fun = @(z) sum(z.^2);
x0 = [1; 2];
result = my_solver(fun, x0);
disp(result);

function x = my_solver(fun, x0, options)
    if nargin < 3
        options = struct();
    end
    if ~isfield(options, 'scale')
        options.scale = 1;
    end
    x = options.scale * fminsearch(fun, x0);
end

% BUG: local solver accepts one argument but OptiProfiler-style caller passes
% the canonical (fun, x0) pair.
fun = @(z) sum(z.^2);
x0 = [1; 2];
result = my_solver(fun, x0);
disp(result);

function x = my_solver(fun, x0)
    x = fminsearch(fun, [0; 0]);
end

